import axios from "axios";

const API_KEY = process.env.CONVERTKIT_API_KEY;
const API_SECRET = process.env.CONVERTKIT_API_SECRET;

const Http = axios.create({
  baseURL: "https://api.convertkit.com/v3",
  headers: {
    "Content-Type": "application/json; charset=utf-8",
  },
});

export function subscribeToForm({
  formId,
  email,
  firstName,
  fields,
}: {
  formId: string;
  email: string;
  firstName: string;
  fields?: Record<string, any>;
}): Promise<Subscriber> {
  return Http(`/forms/${formId}/subscribe`, {
    method: "POST",
    data: { api_key: API_KEY, email, first_name: firstName, fields },
  }).then((res) => res.data.subscription?.subscriber);
}

export function updateSubscriber(
  id: string,
  update: Subscriber
): Promise<unknown> {
  return Http(`/subscribers/${id}`, {
    method: "PUT",
    data: {
      api_secret: API_SECRET,
      ...update,
    },
  }).then((res) => res.data);
}

export interface Subscriber {
  id: number;
  first_name: string;
  email_address: string;
  state: string; // maybe 'active' | 'inactive'
  created_at: string;
  fields: Record<string, any>;
}

export function getSubscriber(id: string): Promise<Subscriber> {
  return Http(`/subscribers/${id}`, {
    method: "GET",
    data: {
      api_secret: API_SECRET,
    },
  }).then((res) => res.data.subscriber);
}

import React, {
  useMemo,
  useCallback,
  useRef,
  useState,
  useEffect,
} from "react";
import matchSorter from "match-sorter";
import cn from "classnames";
import { useRouter } from "next/router";
import Link from "next/link";

const Item = ({ title, active, href, onMouseOver, search }) => {
  const highlight = title.toLowerCase().indexOf(search.toLowerCase());

  return (
    <Link href={href}>
      <a className="block no-underline" onMouseOver={onMouseOver}>
        <li className={cn("p-2", { active })}>
          {title.substring(0, highlight)}
          <span className="highlight">
            {title.substring(highlight, highlight + search.length)}
          </span>
          {title.substring(highlight + search.length)}
        </li>
      </a>
    </Link>
  );
};

const UP = true;
const DOWN = false;

const Search = ({ directories = [] }) => {
  const router = useRouter();
  const [show, setShow] = useState(false);
  const [search, setSearch] = useState("");
  const [active, setActive] = useState(0);
  const input = useRef(null);

  const results = useMemo(() => {
    if (!search) return [];

    // Will need to scrape all the headers from each page and search through them here
    // (similar to what we already do to render the hash links in sidebar)
    // We could also try to search the entire string text from each page
    return matchSorter(directories, search, { keys: ["title"] });
  }, [search]);

  const moveActiveItem = (up) => {
    const position = active + (up ? -1 : 1);
    const { length } = results;

    // Modulo instead of remainder,
    // see https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Operators/Remainder
    const next = (position + length) % length;
    setActive(next);
  };

  const handleKeyDown = useCallback(
    (e) => {
      const { key, ctrlKey } = e;

      if ((ctrlKey && key === "n") || key === "ArrowDown") {
        e.preventDefault();
        moveActiveItem(DOWN);
      }

      if ((ctrlKey && key === "p") || key === "ArrowUp") {
        e.preventDefault();
        moveActiveItem(UP);
      }

      if (key === "Enter") {
        router.push(results[active].route);
      }
    },
    [active, results, router]
  );

  useEffect(() => {
    setActive(0);
  }, [search]);

  useEffect(() => {
    const inputs = ["input", "select", "button", "textarea"];

    const down = (e) => {
      if (
        document.activeElement &&
        inputs.indexOf(document.activeElement.tagName.toLowerCase()) === -1
      ) {
        if (e.key === "/") {
          e.preventDefault();
          input.current.focus();
        } else if (e.key === "Escape") {
          setShow(false);
        }
      }
    };

    window.addEventListener("keydown", down);
    return () => window.removeEventListener("keydown", down);
  }, []);

  const renderList = show && results.length > 0;

  return (
    <div className="relative w-full nextra-search md:w-64">
      {renderList && (
        <div className="z-10 search-overlay" onClick={() => setShow(false)} />
      )}

      <div className="relative flex items-center">
        <div className="absolute inset-y-0 left-0 flex items-center pl-3 pointer-events-none">
          <svg
            xmlns="http://www.w3.org/2000/svg"
            className="w-5 h-5 text-gray-400 dark:text-gray-600"
            fill="none"
            viewBox="0 0 24 24"
            stroke="currentColor"
            aria-hidden="true"
          >
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth={2}
              d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"
            />
          </svg>
        </div>
        <input
          onChange={(e) => {
            setSearch(e.target.value);
            setShow(true);
          }}
          className="block w-full py-2 pl-10 leading-tight border rounded-md appearance-none focus:outline-none focus:ring"
          type="search"
          placeholder="Search docs..."
          onKeyDown={handleKeyDown}
          onFocus={() => setShow(true)}
          onBlur={() => setShow(false)}
          ref={input}
          spellCheck={false}
        />
        {show ? null : (
          <div className="hidden sm:flex absolute inset-y-0 right-0 py-1.5 pr-1.5">
            <kbd className="inline-flex items-center px-2 font-sans text-sm font-medium text-gray-400 border rounded dark:text-gray-800 dark:border-gray-800">
              /
            </kbd>
          </div>
        )}
      </div>
      {renderList && (
        <ul className="absolute left-0 z-20 w-full p-0 m-0 mt-1 list-none border divide-y rounded-md shadow-md md:right-0 top-100 md:w-auto">
          {results.map((res, i) => {
            return (
              <Item
                key={`search-item-${i}`}
                title={res.title}
                href={res.route}
                active={i === active}
                search={search}
                onMouseOver={() => setActive(i)}
              />
            );
          })}
        </ul>
      )}
    </div>
  );
};

export default Search;

import React, {
  useMemo,
  useCallback,
  useRef,
  useState,
  useEffect,
  Fragment,
} from "react";
import Router, { useRouter } from "next/router";
import cn from "classnames";
import Link from "next/link";
import GraphemeSplitter from "grapheme-splitter";

const splitter = new GraphemeSplitter();

const TextWithHighlights = React.memo(function TextWithHighlights({
  content,
  ranges,
}) {
  const splittedText = content ? splitter.splitGraphemes(content) : [];
  const res = [];

  let id = 0,
    index = 0;
  for (const range of ranges) {
    res.push(
      <Fragment key={id++}>
        {splittedText.splice(0, range.beginning - index).join("")}
      </Fragment>
    );
    res.push(
      <span className="highlight" key={id++}>
        {splittedText.splice(0, range.end - range.beginning).join("")}
      </span>
    );
    index = range.end;
  }
  res.push(<Fragment key={id++}>{splittedText.join("")}</Fragment>);

  return res;
});

const Item = ({ title, active, href, onMouseOver, excerpt }) => {
  return (
    <Link href={href}>
      <a className="block no-underline" onMouseOver={onMouseOver}>
        <li className={cn("py-2 px-4", { active })}>
          <span className="font-semibold">{title}</span>
          {excerpt ? (
            <div className="text-gray-600">
              <TextWithHighlights
                content={excerpt.text}
                ranges={excerpt.highlight_ranges}
              />
            </div>
          ) : null}
        </li>
      </a>
    </Link>
  );
};

// This can be global for better caching.
const stork = {};

export default function Search() {
  const router = useRouter();
  const [show, setShow] = useState(false);
  const [search, setSearch] = useState("");
  const [active, setActive] = useState(0);
  const setStork = useState({})[1];
  const input = useRef(null);

  const results = useMemo(() => {
    if (!search) return [];

    const localeCode = Router.locale || "default";
    if (!stork[localeCode]) return [];

    try {
      const json = stork[localeCode].wasm_search(`index-${localeCode}`, search);
      const obj = JSON.parse(json);

      if (!obj.results) return [];
      return obj.results.slice(0, 20).map((result) => {
        return {
          title: result.entry.title,
          route: result.entry.url,
          excerpt: result.excerpts[0],
        };
      });
    } catch (err) {
      console.error(err);
      return [];
    }
  }, [search]);

  const handleKeyDown = useCallback(
    (e) => {
      switch (e.key) {
        case "ArrowDown": {
          e.preventDefault();
          if (active + 1 < results.length) {
            setActive(active + 1);
            const activeElement = document.querySelector(
              `.nextra-stork ul > :nth-child(${active + 2})`
            );
            if (activeElement && activeElement.scrollIntoViewIfNeeded) {
              activeElement.scrollIntoViewIfNeeded();
            }
          }
          break;
        }
        case "ArrowUp": {
          e.preventDefault();
          if (active - 1 >= 0) {
            setActive(active - 1);
            const activeElement = document.querySelector(
              `.nextra-stork ul > :nth-child(${active})`
            );
            if (activeElement && activeElement.scrollIntoViewIfNeeded) {
              activeElement.scrollIntoViewIfNeeded();
            }
          }
          break;
        }
        case "Enter": {
          router.push(results[active].route);
          break;
        }
      }
    },
    [active, results, router]
  );

  const load = async () => {
    const localeCode = Router.locale || "default";
    if (!stork[localeCode]) {
      stork[localeCode] = await import("./wasm-loader");
      setStork({});

      const init = stork[localeCode].init("/stork.wasm");
      const res = await fetch(`/index-${localeCode}.st`);
      const buf = await res.arrayBuffer();
      await init;
      stork[localeCode].wasm_register_index(
        `index-${localeCode}`,
        new Uint8Array(buf)
      );
    }
  };

  useEffect(() => {
    setActive(0);
  }, [search]);

  useEffect(() => {
    const inputs = ["input", "select", "button", "textarea"];

    const down = (e) => {
      if (
        document.activeElement &&
        inputs.indexOf(document.activeElement.tagName.toLowerCase()) === -1
      ) {
        if (e.key === "/") {
          e.preventDefault();
          input.current.focus();
        } else if (e.key === "Escape") {
          setShow(false);
        }
      }
    };

    window.addEventListener("keydown", down);
    return () => window.removeEventListener("keydown", down);
  }, []);

  const renderList = show && results.length > 0;

  return (
    <div className="relative w-full nextra-search nextra-stork md:w-64">
      {renderList && (
        <div className="z-10 search-overlay" onClick={() => setShow(false)} />
      )}
      <div className="relative flex items-center">
        <input
          onChange={(e) => {
            setSearch(e.target.value);
            setShow(true);
          }}
          className="block w-full px-3 py-2 leading-tight border rounded appearance-none focus:outline-none focus:ring"
          type="search"
          placeholder="Search documentation..."
          onKeyDown={handleKeyDown}
          onFocus={() => {
            load();
            setShow(true);
          }}
          onBlur={() => setShow(false)}
          ref={input}
          spellCheck={false}
        />
        {show ? null : (
          <div className="hidden sm:flex absolute inset-y-0 right-0 py-1.5 pr-1.5">
            <kbd className="inline-flex items-center px-2 font-sans text-sm font-medium text-gray-400 border rounded dark:text-gray-800 dark:border-gray-800">
              /
            </kbd>
          </div>
        )}
      </div>
      {renderList && (
        <ul className="absolute z-20 p-0 m-0 mt-1 divide-y top-full">
          {results.map((res, i) => {
            return (
              <Item
                key={`search-item-${i}`}
                title={res.title}
                href={res.route}
                excerpt={res.excerpt}
                active={i === active}
                onMouseOver={() => setActive(i)}
              />
            );
          })}
        </ul>
      )}
    </div>
  );
}

