import { NextApiRequest, NextApiResponse } from "next";
import { subscribeToForm } from "../../lib/ConvertKitApi";

const FORM_ID = process.env.CONVERTKIT_FORM_ID;

export default async function handle(
  req: NextApiRequest,
  res: NextApiResponse
) {
  if (req.method === "POST") {
    const subscriber = await subscribeToForm({
      formId: FORM_ID,
      email: req.body.email,
      firstName: req.body.firstName,
      fields: {
        last_name: req.body.lastName,
      },
    });

    return res.status(201).json(subscriber);
  } else {
    return res.status(404).send(null);
  }
}

import { NextApiRequest, NextApiResponse } from 'next'
import {
  getSubscriber,
  Subscriber,
  updateSubscriber,
} from '../../../lib/ConvertKitApi'

export default async function handle(
  req: NextApiRequest,
  res: NextApiResponse
) {
  try {
    if (req.method === 'PUT') {
      const subscriber = await updateSubscriber(
        req.query.id as string,
        {
          first_name: req.body.first_name,
          email_address: req.body.email_address,
          fields: req.body.fields,
        } as Subscriber
      )
      res.setHeader('Content-Type', 'application/json')
      res.statusCode = 204
      res.json(subscriber)
    } else {
      const subscriber = await getSubscriber(req.query.id as string)
      res.setHeader('Content-Type', 'application/json')
      res.statusCode = 200
      res.json(subscriber)
    }
  } catch (error) {
    console.log(error)
    res.statusCode = 500
    res.json({ okay: false })
  }
}

import supertest from "supertest";
import { createServer } from "../server";

describe("server", () => {
  it("health check returns 200", async () => {
    await supertest(createServer())
      .get("/healthz")
      .expect(200)
      .then((res) => {
        expect(res.body.ok).toBe(true);
      });
  });

  it("message endpoint says hello", async () => {
    await supertest(createServer())
      .get("/message/jared")
      .expect(200)
      .then((res) => {
        expect(res.body).toEqual({ message: "hello jared" });
      });
  });
});

